 3 | pragma solidity ^0.8.9;
 4 | 
 5 | import { SafeTokenCall, SafeTokenTransfer, SafeTokenTransferFrom } from '../gmp-sdk/util/SafeTransfer.sol';
 6 | import { IERC20 } from '../gmp-sdk/interfaces/IERC20.sol';
 7 | import { IAxelarGateway } from './interfaces/IAxelarGateway.sol';
 8 | import { IGovernable } from './interfaces/IGovernable.sol';
 9 | import { IAxelarAuth } from './interfaces/IAxelarAuth.sol';
10 | import { IBurnableMintableCappedERC20 } from './interfaces/IBurnableMintableCappedERC20.sol';
11 | import { ITokenDeployer } from './interfaces/ITokenDeployer.sol';
12 | 
13 | import { ECDSA } from './ECDSA.sol';
14 | import { DepositHandler } from './DepositHandler.sol';
15 | import { AdminMultisigBase } from './AdminMultisigBase.sol';
16 | 
17 | contract AxelarGateway is IAxelarGateway, IGovernable, AdminMultisigBase {
18 |     using SafeTokenCall for IERC20;
19 |     using SafeTokenTransfer for IERC20;
20 |     using SafeTokenTransferFrom for IERC20;
21 | 
22 |     error InvalidImplementation();
23 | 
24 |     enum TokenType {
25 |         InternalBurnable,
26 |         InternalBurnableFrom,
27 |         External
28 |     }
29 | 
30 |     /// @dev Removed slots; Should avoid re-using
31 |     // bytes32 internal constant KEY_ALL_TOKENS_FROZEN = keccak256('all-tokens-frozen');
32 |     // bytes32 internal constant PREFIX_TOKEN_FROZEN = keccak256('token-frozen');
33 | 
34 |     /// @dev Storage slot with the address of the current implementation. `keccak256('eip1967.proxy.implementation') - 1`.
35 |     bytes32 internal constant KEY_IMPLEMENTATION = bytes32(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc);
36 | 
37 |     /// @dev Storage slot with the address of the current governance. `keccak256('governance') - 1`.
38 |     bytes32 internal constant KEY_GOVERNANCE = bytes32(0xabea6fd3db56a6e6d0242111b43ebb13d1c42709651c032c7894962023a1f909);
39 | 
40 |     /// @dev Storage slot with the address of the current governance. `keccak256('mint-limiter') - 1`.
41 |     bytes32 internal constant KEY_MINT_LIMITER = bytes32(0x627f0c11732837b3240a2de89c0b6343512886dd50978b99c76a68c6416a4d92);
42 | 
43 |     // AUDIT: slot names should be prefixed with some standard string
44 |     bytes32 internal constant PREFIX_COMMAND_EXECUTED = keccak256('command-executed');
45 |     bytes32 internal constant PREFIX_TOKEN_ADDRESS = keccak256('token-address');
